# Generated by tools/update_migration_worker.py; review and pin after changes.
function Get-DomeniaMigrationWorkerCode {
return @'
function Get-StoreWLeaseName {
    param([string]$Path)
    $full=[IO.Path]::GetFullPath($Path).ToLowerInvariant();$sha=[Security.Cryptography.SHA256]::Create()
    try{$key=[BitConverter]::ToString($sha.ComputeHash([Text.Encoding]::UTF8.GetBytes($full))).Replace('-','')}finally{$sha.Dispose()}
    $prefix=if([Environment]::OSVersion.Platform -eq [PlatformID]::Win32NT){'Global\'}else{''}
    return $prefix+'Domenia.SQLite.'+$key
}

function Enter-StoreWDatabaseLease {
    param([string]$Path,[int]$TimeoutMs=1000)
    $mutex=[Threading.Mutex]::new($false,(Get-StoreWLeaseName $Path));$held=$false
    try{try{$held=$mutex.WaitOne([Math]::Max(0,[Math]::Min(5000,$TimeoutMs)))}catch [Threading.AbandonedMutexException]{$held=$true};if(-not $held){throw 'StorageBusy : autre ecriture ou maintenance locale en cours.'};return $mutex}catch{$mutex.Dispose();throw}
}

function Exit-StoreWDatabaseLease {
    param($Lease)
    if($null -ne $Lease){try{$Lease.ReleaseMutex()}finally{$Lease.Dispose()}}
}

function Read-StoreWLeaseScalar {
    param([IntPtr]$Db,[string]$Sql)
    $bytes=[Text.Encoding]::UTF8.GetBytes($Sql+[char]0);$ptr=[Runtime.InteropServices.Marshal]::AllocHGlobal($bytes.Length);$stmt=[IntPtr]::Zero
    try{
        [Runtime.InteropServices.Marshal]::Copy($bytes,0,$ptr,$bytes.Length)
        $rc=[Domenia.WinSqliteNative]::sqlite3_prepare_v2($Db,$ptr,-1,[ref]$stmt,[IntPtr]::Zero);if($rc -ne 0){throw ('Controle du stockage impossible : SQLite '+$rc)}
        $rc=[Domenia.WinSqliteNative]::sqlite3_step($stmt);if($rc -eq 101){return ''};if($rc -ne 100){throw ('Controle du stockage impossible : SQLite '+$rc)}
        $n=[Domenia.WinSqliteNative]::sqlite3_column_bytes($stmt,0);if($n -le 0){return ''};$value=New-Object byte[] $n;[Runtime.InteropServices.Marshal]::Copy([Domenia.WinSqliteNative]::sqlite3_column_text($stmt,0),$value,0,$n);return [Text.Encoding]::UTF8.GetString($value)
    }finally{if($stmt -ne [IntPtr]::Zero){[void][Domenia.WinSqliteNative]::sqlite3_finalize($stmt)};[Runtime.InteropServices.Marshal]::FreeHGlobal($ptr)}
}

function Assert-StoreWDatabaseWritable {
    param([IntPtr]$Db)
    if((Read-StoreWLeaseScalar $Db "SELECT name FROM sqlite_master WHERE type='table' AND name='domenia_store_redirect';")){
        $redirect=Read-StoreWLeaseScalar $Db "SELECT target_path FROM domenia_store_redirect WHERE id=1;"
        if($redirect){throw ('StorageRedirected : cette base est conservee en lecture seule apres bascule. Reprendre la base verifiee : '+$redirect)}
    }
}

function Initialize-DomeniaWinSqliteNative { return [Domenia.WinSqliteNative] }

function New-DomeniaUtf8Ptr {
    param([AllowEmptyString()][string]$Text)
    $bytes = [System.Text.Encoding]::UTF8.GetBytes(([string]$Text) + [char]0)
    $ptr = [System.Runtime.InteropServices.Marshal]::AllocHGlobal($bytes.Length)
    [System.Runtime.InteropServices.Marshal]::Copy($bytes,0,$ptr,$bytes.Length)
    return $ptr
}

function ConvertFrom-DomeniaUtf8Ptr {
    param([IntPtr]$Pointer,[int]$Length = -1)
    if ($Pointer -eq [IntPtr]::Zero) { return "" }
    if ($Length -lt 0) {
        $Length = 0
        while ([System.Runtime.InteropServices.Marshal]::ReadByte($Pointer,$Length) -ne 0) { $Length++ }
    }
    if ($Length -le 0) { return "" }
    $bytes = New-Object byte[] $Length
    [System.Runtime.InteropServices.Marshal]::Copy($Pointer,$bytes,0,$Length)
    return [System.Text.Encoding]::UTF8.GetString($bytes)
}

function Close-DomeniaDatabase {
    param([IntPtr]$DatabaseHandle)
    if($DatabaseHandle -eq [IntPtr]::Zero){return}
    Initialize-DomeniaWinSqliteNative | Out-Null
    $closed=[Domenia.WinSqliteNative]::sqlite3_close($DatabaseHandle)
    if($closed -ne 0){throw ('Fermeture SQLite non confirmee (code '+$closed+'). Le verrou est conserve.')}
    if($null -ne $script:StoreWHandleLeases -and $script:StoreWHandleLeases.ContainsKey($DatabaseHandle.ToInt64())){$lease=$script:StoreWHandleLeases[$DatabaseHandle.ToInt64()];$script:StoreWHandleLeases.Remove($DatabaseHandle.ToInt64());Exit-StoreWDatabaseLease $lease}
}

function ConvertTo-DomeniaSqlLiteral {
    param($Value)
    if ($null -eq $Value) { return "NULL" }
    if ($Value -is [bool]) { return $(if ($Value) { "1" } else { "0" }) }
    if ($Value -is [byte] -or $Value -is [int16] -or $Value -is [int32] -or $Value -is [int64] -or $Value -is [double] -or $Value -is [decimal]) { return ([Convert]::ToString($Value,[Globalization.CultureInfo]::InvariantCulture)) }
    return "'" + (([string]$Value) -replace "'","''") + "'"
}

function Open-DomeniaDatabase {
    param([string]$Path = '',[switch]$ReadOnly)
    $native = Initialize-DomeniaWinSqliteNative
    $db = [IntPtr]::Zero
    $pathPtr = [IntPtr]::Zero;$writeLease=$null
    try {
        if ([string]::IsNullOrWhiteSpace($Path)) { $Path = Get-DomeniaDatabasePath }
        if(-not $ReadOnly){$writeLease=Enter-StoreWDatabaseLease -Path $Path}
        $pathPtr = New-DomeniaUtf8Ptr $Path
        $flags = if ($ReadOnly) { 1 -bor 65536 } else { 2 -bor 4 -bor 65536 }
        $rc = [Domenia.WinSqliteNative]::sqlite3_open_v2($pathPtr,[ref]$db,$flags,[IntPtr]::Zero)
        if ($rc -ne 0 -or $db -eq [IntPtr]::Zero) { throw "Ouverture SQLite impossible (code $rc)." }
        # FI-12: lock wait from the worker context (LocalStore.DatabaseBusyTimeoutMs), 2 500 ms without one.
        $busyMs=2500;$workerContext=Get-Variable -Name Context -ValueOnly -ErrorAction SilentlyContinue
        if(($null -ne $workerContext) -and ($null -ne $workerContext.PSObject.Properties['BusyTimeoutMs'])){$busyMs=[Math]::Max(100,[Math]::Min(5000,[int]$workerContext.BusyTimeoutMs))}
        [void][Domenia.WinSqliteNative]::sqlite3_busy_timeout($db,$busyMs)
        if(-not $ReadOnly){Assert-StoreWDatabaseWritable $db;if($null -eq $script:StoreWHandleLeases){$script:StoreWHandleLeases=@{}};$script:StoreWHandleLeases[$db.ToInt64()]=$writeLease;$writeLease=$null}
        return $db
    }
    catch {
        # sqlite3_open_v2 can return a non-null handle even on failure.
        if ($db -ne [IntPtr]::Zero) { [void][Domenia.WinSqliteNative]::sqlite3_close($db) }
        if($null -ne $writeLease){Exit-StoreWDatabaseLease $writeLease}
        throw
    }
    finally { if ($pathPtr -ne [IntPtr]::Zero) { [Runtime.InteropServices.Marshal]::FreeHGlobal($pathPtr) } }
}

function Invoke-DomeniaDbQuery {
    param([Parameter(Mandatory=$true)][AllowEmptyString()][string]$Sql,[IntPtr]$DatabaseHandle = [IntPtr]::Zero)
    $own = ($DatabaseHandle -eq [IntPtr]::Zero)
    $sqlPtr = [IntPtr]::Zero
    $stmt = [IntPtr]::Zero
    $rows = New-Object System.Collections.Generic.List[object]
    try {
        if ($own) { $DatabaseHandle = Open-DomeniaDatabase }
        $native = Initialize-DomeniaWinSqliteNative
        $sqlPtr = New-DomeniaUtf8Ptr $Sql
        $rc = [Domenia.WinSqliteNative]::sqlite3_prepare_v2($DatabaseHandle,$sqlPtr,-1,[ref]$stmt,[IntPtr]::Zero)
        if ($rc -ne 0) { throw "SQLite prepare code $rc : $(ConvertFrom-DomeniaUtf8Ptr ([Domenia.WinSqliteNative]::sqlite3_errmsg($DatabaseHandle)))" }
        $count = [Domenia.WinSqliteNative]::sqlite3_column_count($stmt)
        while (($step = [Domenia.WinSqliteNative]::sqlite3_step($stmt)) -eq 100) {
            $o = [ordered]@{}
            for ($i=0;$i -lt $count;$i++) {
                $name = ConvertFrom-DomeniaUtf8Ptr ([Domenia.WinSqliteNative]::sqlite3_column_name($stmt,$i))
                $type = [Domenia.WinSqliteNative]::sqlite3_column_type($stmt,$i)
                $value = $null
                switch ($type) {
                    1 { $value = [long][Domenia.WinSqliteNative]::sqlite3_column_int64($stmt,$i) }
                    2 { $value = [double][Domenia.WinSqliteNative]::sqlite3_column_double($stmt,$i) }
                    3 { $p=[Domenia.WinSqliteNative]::sqlite3_column_text($stmt,$i); $n=[Domenia.WinSqliteNative]::sqlite3_column_bytes($stmt,$i); $value=ConvertFrom-DomeniaUtf8Ptr $p $n }
                    5 { $value = $null }
                    default { $p=[Domenia.WinSqliteNative]::sqlite3_column_text($stmt,$i); $n=[Domenia.WinSqliteNative]::sqlite3_column_bytes($stmt,$i); $value=ConvertFrom-DomeniaUtf8Ptr $p $n }
                }
                $o[$name] = $value
            }
            $rows.Add([pscustomobject]$o)
        }
        if ($step -ne 101) { throw "SQLite step code $step : $(ConvertFrom-DomeniaUtf8Ptr ([Domenia.WinSqliteNative]::sqlite3_errmsg($DatabaseHandle)))" }
        return $rows.ToArray()
    }
    finally {
        if ($stmt -ne [IntPtr]::Zero) { try { Initialize-DomeniaWinSqliteNative | Out-Null; [void][Domenia.WinSqliteNative]::sqlite3_finalize($stmt) } catch { } }
        if ($sqlPtr -ne [IntPtr]::Zero) { [System.Runtime.InteropServices.Marshal]::FreeHGlobal($sqlPtr) }
        if ($own) { Close-DomeniaDatabase $DatabaseHandle }
    }
}

function Test-DomeniaDictionaryKey {
    # IDictionary.Contains is explicit on generic dictionaries: it throws under Windows PowerShell 5.1.
    param([Collections.IDictionary]$Dictionary,[string]$Name)
    try { return [bool]$Dictionary.Contains($Name) }
    catch { try { return [bool]$Dictionary.ContainsKey($Name) } catch { return $false } }
}

function Get-DomeniaMember {
    # Safe member read for PSCustomObject, hashtable and .NET objects. Never throws on a missing member.
    # Calling convention (relied on by every rule module): the value is written to the pipeline, so a collection is
    # enumerated; wrap the call in @() to read a collection, cast to read a scalar. Get-DomeniaMemberValue returns the
    # value itself (one-element collection, byte[] GUID or SID) when the exact object is needed.
    param($InputObject,[string]$Name,$Default=$null)
    if ($null -eq $InputObject -or [string]::IsNullOrEmpty($Name)) { return $Default }
    if ($InputObject -is [Collections.IDictionary]) {
        if (Test-DomeniaDictionaryKey $InputObject $Name) { return $InputObject[$Name] }
        return $Default
    }
    $property = $InputObject.PSObject.Properties[$Name]
    if ($null -eq $property) { return $Default }
    return $property.Value
}

function Get-DomeniaCollectionItems {
    # Materialises any non-text collection (array, AD value collection, list) as object[]; a scalar gives one item.
    # byte[] is a single AD value (GUID, SID), never a collection of values.
    param($Value)
    if ($null -eq $Value) { return ,([object[]]@()) }
    if (($Value -is [string]) -or ($Value -is [byte[]])) { return ,([object[]]@(,$Value)) }
    if ($Value -is [Collections.IEnumerable]) {
        $items = New-Object 'System.Collections.Generic.List[object]'
        foreach ($item in $Value) { $items.Add($item) }
        return ,($items.ToArray())
    }
    return ,([object[]]@(,$Value))
}

function ConvertFrom-DomeniaLargeInteger {
    # Reads an ADSI IADsLargeInteger (DirectoryEntry large-integer attribute) as Int64. $null when not one.
    param($Value)
    if ($null -eq $Value -or $Value -is [ValueType] -or $Value -is [string] -or $Value -is [Collections.IEnumerable]) { return $null }
    try {
        $type = $Value.GetType()
        $high = $type.InvokeMember('HighPart',[Reflection.BindingFlags]::GetProperty,$null,$Value,$null)
        $low = $type.InvokeMember('LowPart',[Reflection.BindingFlags]::GetProperty,$null,$Value,$null)
        if ($null -eq $high -or $null -eq $low) { return $null }
        return (([long][int]$high) * 4294967296L) + (([long][int]$low) -band 0xFFFFFFFFL)
    } catch { return $null }
}

function Get-DomeniaTextHash {
    param([AllowEmptyString()][string]$Text)
    $sha = [Security.Cryptography.SHA256]::Create()
    try { return ([BitConverter]::ToString($sha.ComputeHash([Text.Encoding]::UTF8.GetBytes([string]$Text)))).Replace('-','') }
    finally { $sha.Dispose() }
}

function ConvertTo-DomeniaUtcDate {
    # Returns a UTC DateTime or $null. Accepts DateTime, ISO text, and an AD FILETIME (Int64 ticks since 1601).
    # A text or DateTime without offset is UTC by default; -AssumeLocal reads it as local time instead (CO-29: the
    # relation dates written before RC1.14 as local "yyyy-MM-dd HH:mm:ss"). An explicit offset or Z always wins.
    param($Value,[switch]$AssumeLocal)
    if ($null -eq $Value) { return $null }
    try {
        if ($Value -is [byte[]]) { return $null }
        if (($Value -isnot [string]) -and ($Value -is [Collections.IEnumerable])) {
            # One AD value in a collection is read; several values never pick one silently.
            $items = Get-DomeniaCollectionItems $Value
            if ($items.Count -ne 1) { return $null }
            return (ConvertTo-DomeniaUtcDate $items[0] -AssumeLocal:$AssumeLocal)
        }
        $large = ConvertFrom-DomeniaLargeInteger $Value
        if ($null -ne $large) { $Value = [long]$large }
        if ($Value -is [datetime]) {
            if ($Value.Kind -eq [DateTimeKind]::Unspecified) {
                if ($AssumeLocal) { return [datetime]::SpecifyKind($Value,[DateTimeKind]::Local).ToUniversalTime() }
                return [datetime]::SpecifyKind($Value,[DateTimeKind]::Utc)
            }
            return $Value.ToUniversalTime()
        }
        if ($Value -is [long] -or $Value -is [int] -or $Value -is [decimal] -or $Value -is [double]) {
            $ticks = [long]$Value
            # 0 and 0x7FFFFFFFFFFFFFFF both mean "never" for AD time attributes.
            if ($ticks -le 0 -or $ticks -eq [long]::MaxValue) { return $null }
            return [datetime]::FromFileTimeUtc($ticks)
        }
        $text = ([string]$Value).Trim()
        if (-not $text) { return $null }
        $number = 0L
        if ($text -match '^\d{12,19}$' -and [long]::TryParse($text,[ref]$number)) {
            if ($number -le 0 -or $number -eq [long]::MaxValue) { return $null }
            return [datetime]::FromFileTimeUtc($number)
        }
        $parsed = [datetime]::MinValue
        $assumed = [Globalization.DateTimeStyles]::AssumeUniversal
        if ($AssumeLocal) { $assumed = [Globalization.DateTimeStyles]::AssumeLocal }
        $styles = $assumed -bor [Globalization.DateTimeStyles]::AdjustToUniversal
        if ([datetime]::TryParse($text,[Globalization.CultureInfo]::InvariantCulture,$styles,[ref]$parsed)) { return $parsed }
    } catch { if (${function:Write-DomeniaRuleSwallowed}) { Write-DomeniaRuleSwallowed 'Common' 'ConvertTo-DomeniaUtcDate' $_ } }
    return $null
}

function Test-DomeniaReleaseMapKey {
    # Key lookup that works on every map a caller may pass: a hashtable, an ordered dictionary, or a generic
    # Dictionary[string,T] whose IDictionary.Contains is an explicit interface member that Windows PowerShell 5.1 cannot
    # call directly. The map keeps its own comparer (case-insensitive hashtable, ordinal Dictionary).
    param($Map,[AllowNull()][AllowEmptyString()][string]$Key)
    if (($null -eq $Map) -or ($null -eq $Key)) { return $false }
    if ($Map -is [hashtable]) { return $Map.ContainsKey($Key) }
    if ($null -ne $Map.PSObject.Methods['ContainsKey']) { return [bool]$Map.ContainsKey($Key) }
    if ($null -ne $Map.PSObject.Methods['Contains']) { return [bool]$Map.Contains($Key) }
    if ($Map -is [Collections.IDictionary]) { return [bool]([Collections.IDictionary].GetMethod('Contains').Invoke($Map.PSObject.BaseObject,[object[]]@($Key))) }
    return ($null -ne $Map.PSObject.Properties[$Key])
}

function Get-DomeniaReleaseMapValue {
    # Value of a key in any map (see Test-DomeniaReleaseMapKey) or a property of an object; $Default when absent.
    param($Map,[AllowNull()][AllowEmptyString()][string]$Key,$Default=$null)
    if ($null -eq $Map) { return $Default }
    if ($Map -is [Collections.IDictionary]) {
        if (Test-DomeniaReleaseMapKey $Map $Key) { return $Map[$Key] }
        return $Default
    }
    return (Get-DomeniaMember $Map $Key $Default)
}

function ConvertTo-DomeniaMigrationDomain {
    # Domain identity for the migration check: DNS name in lower case. A DN made of DC= parts is converted;
    # any other DN (OU=, CN=) is not a domain and yields ''. A short NetBIOS name stays as it is.
    param([AllowNull()][AllowEmptyString()][string]$Domain)
    $text = ([string]$Domain).Trim().TrimEnd('.')
    if (-not $text) { return '' }
    if ($text -match '(?i)^DC\s*=') {
        $labels = New-Object 'System.Collections.Generic.List[string]'
        foreach ($part in $text.Split([char]',')) {
            $pair = [regex]::Match($part.Trim(),'(?i)^DC\s*=\s*(.+)$')
            if (-not $pair.Success) { return '' }
            $labels.Add($pair.Groups[1].Value.Trim())
        }
        $text = [string]::Join('.',$labels.ToArray())
    }
    elseif ($text.IndexOf([char]'=') -ge 0) { return '' }
    return $text.ToLowerInvariant()
}

function ConvertTo-DomeniaMigrationComputerKey {
    # Key of the core table user_machine_links (computer_key, as Normalize-LinkComputer builds it): text trimmed, the
    # trailing '$' of a machine account removed, first DNS label only, upper case. '' when unusable.
    param([AllowNull()][AllowEmptyString()][string]$Computer)
    $text = ([string]$Computer).Trim().Trim([char[]]@([char]34,[char]32,[char]9,[char]13,[char]10))
    if ($text.EndsWith('$',[StringComparison]::Ordinal)) { $text = $text.Substring(0,$text.Length - 1) }
    if ($text.IndexOf([char]'.') -ge 0) { $text = $text.Split([char]'.')[0] }
    return $text.ToUpperInvariant()
}

function ConvertTo-DomeniaMigrationUserLogin {
    # Same reading as Normalize-LinkUser in the core: domain prefix and UPN suffix removed; a machine account or a
    # built-in account is not a user. '' when unusable.
    param([AllowNull()][AllowEmptyString()][string]$User)
    $text = ([string]$User).Trim().Trim([char[]]@([char]34,[char]32,[char]9,[char]13,[char]10))
    if (-not $text) { return '' }
    if ($text.IndexOf([char]92) -ge 0) { $text = $text.Split([char]92)[-1] }
    if ($text.IndexOf([char]'@') -ge 0) { $text = $text.Split([char]'@')[0] }
    if ($text.EndsWith('$',[StringComparison]::Ordinal)) { return '' }
    if ($text.ToUpperInvariant() -in @('SYSTEM','LOCAL SERVICE','NETWORK SERVICE','ANONYMOUS LOGON','DWM-1','DWM-2','UMFD-0','UMFD-1','DEFAULTUSER0','ADMINISTRATEUR','ADMINISTRATOR')) { return '' }
    return $text
}

function Get-DomeniaMigrationPlan {
    # Explicit ADCC to Domenia migration plan, built on what the runtime really does:
    # - preferences: wad\ADCC.<name> is copied to wad\Domenia.<name> only when that file is absent, as
    #   INSTALLER-MISE-A-JOUR.ps1 does; the ADCC file is kept and a Domenia file already created always wins;
    # - database: Get-DomeniaDatabasePath adopts ADCC.db IN PLACE (no copy) and Initialize-DomeniaDatabase adds the
    #   domenia_schema revision after Backup-DomeniaDatabase. The file keeps its name but is modified: adoption needs
    #   schema_version 11, the same domain (base_dn of sync_state) and a backup;
    # - stores: Import-DomeniaLegacyStoreIfNeeded fills one Domenia table from objets.tsv, parc.tsv, recherches.tsv,
    #   secrets-etat.tsv only when the four target tables are empty. Existing workstation links are never replaced.
    #   The caller canonicalizes links through Relations before planning: declared assignment, then most recent.
    # $Legacy: ConfigFiles (wad\ADCC.* names), Domain (domain of the TSV/CSV data, read by the caller from their DN
    # columns), Stores (Kind = Objets, Parc, Recherches, Secrets or Liens; Path; Rows; Links for Liens).
    # $Current: ConfigFiles (wad\Domenia.* names), Domain, Database (Name, SchemaVersion, DomeniaSchema, BaseDn of the
    # file Get-DomeniaDatabasePath selected; $null when none exists yet), Tables (table -> row count), Links.
    # A refused plan writes nothing: every write it would have made is listed as 'Reporter'.
    param(
        $Legacy,$Current,
        [string[]]$SupportedSchemaVersions=@('11'),
        [string[]]$PreservedNames=@('Domenia.config.json','Domenia.login-mode.cfg','Domenia.theme.cfg','Domenia.ui-profile.cfg'),
        [ValidateSet('Explicit','Startup')][string]$Trigger='Explicit'
    )
    $steps = New-Object 'System.Collections.Generic.List[object]'
    $trace = New-Object 'System.Collections.Generic.List[object]'
    $blockers = New-Object 'System.Collections.Generic.List[string]'
    $tableOf = @{Objets='ad_objects';Parc='park_state';Liens='user_machine_links';Recherches='user_scan_history';Secrets='secret_state'}
    $currentDomain = ConvertTo-DomeniaMigrationDomain ([string](Get-DomeniaMember $Current 'Domain' ''))
    $addStep = {
        param([string]$Kind,[string]$Action,[string]$Source,[string]$Target,[string]$Reason,[string]$Key,$Item)
        $steps.Add([pscustomobject]@{Kind=$Kind;Action=$Action;Planned=$Action;Source=$Source;Target=$Target;Reason=$Reason;Key=$Key;Item=$Item})
    }
    $checkDomain = {
        param([string]$Origin,[string]$Domain)
        if (-not $Domain) { $blockers.Add('Domaine ' + $Origin + ' non identifie : aucune reprise de donnees.'); return }
        if (-not $currentDomain) { $blockers.Add('Domaine courant inconnu : reprise des donnees reportee.'); return }
        if ($Domain -cne $currentDomain) { $blockers.Add('Domaine different (' + $Origin + ' : ' + $Domain + ' ; Domenia : ' + $currentDomain + ') : aucune fusion entre domaines.') }
    }
    if ($Trigger -cne 'Explicit') { $blockers.Add('Reprise des anciennes donnees non lancee au demarrage : elle part seulement d un geste explicite de l operateur.') }

    # Preferences kept by the installer.
    $preserved = @{}
    foreach ($name in @($PreservedNames)) { if ($name) { $preserved[[string]$name] = $true } }
    $currentConfig = @{}
    foreach ($name in @(Get-DomeniaMember $Current 'ConfigFiles' @())) { if ($name) { $currentConfig[[string]$name] = $true } }
    foreach ($name in @(Get-DomeniaMember $Legacy 'ConfigFiles' @())) {
        $sourceName = [string]$name
        if (-not $sourceName) { continue }
        $found = [regex]::Match($sourceName,'^(?i:ADCC)\.([A-Za-z0-9][A-Za-z0-9._-]*)$')
        if (-not $found.Success) { & $addStep 'Configuration' 'Ignorer' $sourceName '' 'Nom non reconnu comme preference historique : fichier conserve, non repris.' '' $null; continue }
        $targetName = 'Domenia.' + $found.Groups[1].Value
        if (-not $preserved.ContainsKey($targetName)) { & $addStep 'Configuration' 'Ignorer' $sourceName '' 'Fichier historique sans equivalent Domenia : conserve, non repris.' '' $null; continue }
        if ($currentConfig.ContainsKey($targetName)) {
            & $addStep 'Configuration' 'Conserver' $sourceName $targetName 'Configuration Domenia deja presente : elle n est pas ecrasee.' $targetName $null
            $trace.Add([pscustomobject]@{Ancien=$sourceName;Nouveau=$targetName;Decision='Non repris : configuration Domenia conservee'})
            continue
        }
        $currentConfig[$targetName] = $true
        & $addStep 'Configuration' 'Copier' $sourceName $targetName 'Copie sous le nom Domenia ; le fichier historique est conserve.' $targetName $null
        $trace.Add([pscustomobject]@{Ancien=$sourceName;Nouveau=$targetName;Decision='Repris sous le nouveau nom ; fichier historique conserve'})
    }

    # Database selected by the core: Domenia.db, or ADCC.db adopted in place.
    $database = Get-DomeniaMember $Current 'Database' $null
    if ($null -ne $database) {
        $databaseName = [string](Get-DomeniaMember $database 'Name' 'Domenia.db')
        $schemaVersion = ([string](Get-DomeniaMember $database 'SchemaVersion' '')).Trim()
        $revision = ([string](Get-DomeniaMember $database 'DomeniaSchema' '')).Trim()
        if ((-not $schemaVersion) -or ($SupportedSchemaVersions -cnotcontains $schemaVersion)) {
            $blockers.Add('Version de base non prise en charge : <' + $schemaVersion + '>. Base ' + $databaseName + ' conservee telle quelle, aucune ecriture ; migration explicite requise.')
            & $addStep 'Base' 'Refuser' $databaseName '' 'Version de schema non prise en charge : base intacte.' '' $null
        }
        elseif ($revision -and ($revision -cne '1')) {
            $blockers.Add('Revision Domenia de la base non prise en charge : <' + $revision + '>. Base ' + $databaseName + ' intacte.')
            & $addStep 'Base' 'Refuser' $databaseName '' 'Revision Domenia inconnue : base intacte.' '' $null
        }
        elseif (-not $revision) {
            & $checkDomain ('de la base ' + $databaseName) (ConvertTo-DomeniaMigrationDomain ([string](Get-DomeniaMember $database 'BaseDn' '')))
            & $addStep 'Base' 'Adopter' $databaseName $databaseName 'Base historique adoptee sur place apres sauvegarde verifiee : ajout de la revision domenia_schema et de la table domenia_provenance. Le fichier garde son nom ; aucune donnee supprimee ni recreee.' $databaseName $null
            $trace.Add([pscustomobject]@{Ancien=$databaseName;Nouveau=($databaseName + ' (adoptee sur place)');Decision='Nom historique conserve ; fichier modifie apres sauvegarde (revision domenia_schema ajoutee)'})
        }
    }

    # TSV and CSV stores: four empty tables; existing workstation links are preserved.
    $tables = Get-DomeniaMember $Current 'Tables' $null
    $legacyDomain = ConvertTo-DomeniaMigrationDomain ([string](Get-DomeniaMember $Legacy 'Domain' ''))
    $marker = [string](Get-DomeniaMember $Legacy 'Marker' '')
    if (-not $marker) { $marker = Get-DomeniaTextHash ($Legacy | ConvertTo-Json -Depth 12 -Compress) }
    $existingMarker = [string](Get-DomeniaMember $Current 'MigrationMarker' '')
    $already = ($existingMarker -and ($existingMarker -ceq $marker))
    if ($existingMarker -and (-not $already)) { $blockers.Add('Une autre reprise de donnees a deja ete appliquee : aucun ajout automatique.') }
    $stores = @(@(Get-DomeniaMember $Legacy 'Stores' @()) | Where-Object { $null -ne $_ })
    if ($stores.Count -gt 0 -and (-not $already)) {
        foreach ($tableName in @('ad_objects','park_state','user_scan_history','secret_state')) {
            $n = Get-DomeniaReleaseMapValue $tables $tableName $null
            if ($null -eq $n) { $blockers.Add('Etat de la table ' + $tableName + ' inconnu.') }
            elseif ([long]$n -gt 0) { $blockers.Add('La table ' + $tableName + ' contient deja des donnees : reprise refusee.') }
        }
    }
    $existingComputers = @{}
    foreach ($link in @(Get-DomeniaMember $Current 'Links' @())) {
        $key = ConvertTo-DomeniaMigrationComputerKey ([string](Get-DomeniaMember $link 'Computer' ''))
        if ($key) { $existingComputers[$key] = $true }
    }
    $taken = @{}
    $domainChecked = $false
    foreach ($store in @(Get-DomeniaMember $Legacy 'Stores' @())) {
        if ($null -eq $store) { continue }
        $kind = [string](Get-DomeniaMember $store 'Kind' '')
        $path = [string](Get-DomeniaMember $store 'Path' '')
        $leaf = $path.Replace('/','\').Split([char]92)[-1]
        if (-not $tableOf.ContainsKey($kind)) { & $addStep 'Source' 'Ignorer' $path '' 'Source historique non reconnue : conservee, non reprise.' '' $null; continue }
        $kind = [string]@($tableOf.Keys | Where-Object { $_ -ieq $kind })[0]
        $table = [string]$tableOf[$kind]
        $links = @(@(Get-DomeniaMember $store 'Links' @()) | Where-Object { $null -ne $_ })
        $rows = 0
        if ($kind -ceq 'Liens') { $rows = $links.Count }
        else { [void][int]::TryParse([string](Get-DomeniaMember $store 'Rows' 0),[ref]$rows) }
        if ($already) { & $addStep 'Source' 'Ignorer' $path $table 'Reprise identique deja appliquee : rien a ecrire.' '' $null; continue }
        if ($rows -le 0) { & $addStep 'Source' 'Ignorer' $path $table 'Source vide : rien a reprendre.' '' $null; continue }
        $filled = Get-DomeniaReleaseMapValue $tables $table $null
        $count = -1
        if ($null -ne $filled) { [void][int]::TryParse([string]$filled,[ref]$count) }
        if ($count -lt 0) { & $addStep 'Source' 'Ignorer' $path $table ('Etat de la table ' + $table + ' non fourni : rien n est repris.') '' $null; continue }
        if (($count -gt 0) -and ($kind -cne 'Liens')) {
            & $addStep 'Source' 'Ignorer' $path $table ('Table ' + $table + ' deja alimentee dans Domenia : aucune fusion ni remplacement.') '' $null
            $trace.Add([pscustomobject]@{Ancien=$leaf;Nouveau=$table;Decision='Non repris : donnees Domenia conservees'})
            continue
        }
        if ($taken.ContainsKey($table)) { & $addStep 'Source' 'Ignorer' $path $table ('Une source est deja reprise pour ' + $table + ' : la premiere trouvee est retenue, comme dans le coeur.') '' $null; continue }
        $taken[$table] = $true
        if (-not $domainChecked) { & $checkDomain 'des fichiers historiques' $legacyDomain; $domainChecked = $true }
        $trace.Add([pscustomobject]@{Ancien=$leaf;Nouveau=$table;Decision=('Repris dans la table ' + $table + ' ; fichier historique conserve')})
        if ($kind -cne 'Liens') {
            & $addStep 'Source' 'Importer' $path $table ([string]$rows + ' ligne(s) reprises dans une table vide ; fichier historique conserve.') $table ([pscustomobject]@{Table=$table;Rows=$rows})
            continue
        }
        # Links: canonical as ConvertTo-DomeniaCanonicalLinks, most recent first, one per computer.
        $indexed = New-Object 'System.Collections.Generic.List[object]'
        for ($i = 0; $i -lt $links.Count; $i++) { $indexed.Add([pscustomobject]@{Index=$i;When=[string](Get-DomeniaMember $links[$i] 'When' '');Link=$links[$i]}) }
        $ordered = @($indexed.ToArray() | Sort-Object -Property @{Expression={$_.When};Descending=$true},@{Expression={$_.Index};Ascending=$true})
        $seenComputers = @{}
        foreach ($entry in $ordered) {
            $link = $entry.Link
            $user = ConvertTo-DomeniaMigrationUserLogin ([string](Get-DomeniaMember $link 'UserLogin' ''))
            $computerKey = ConvertTo-DomeniaMigrationComputerKey ([string](Get-DomeniaMember $link 'Computer' ''))
            $label = [string](Get-DomeniaMember $link 'UserLogin' '') + ' / ' + [string](Get-DomeniaMember $link 'Computer' '')
            if ((-not $user) -or (-not $computerKey)) { & $addStep 'Lien' 'Rejeter' $label '' 'Lien incomplet : utilisateur ou poste absent ou non reconnu.' '' $null; continue }
            if ($seenComputers.ContainsKey($computerKey)) { & $addStep 'Lien' 'Ignorer' $label '' 'Poste deja repris depuis un lien plus recent : la table garde un lien par poste.' $computerKey $null; continue }
            $seenComputers[$computerKey] = $true
            if ($existingComputers.ContainsKey($computerKey)) {
                & $addStep 'Lien' 'Conserver' $label $table 'Association Domenia existante : aucun remplacement.' $computerKey $null
                continue
            }
            & $addStep 'Lien' 'Ajouter' $label $table 'Lien repris avec sa source et sa date d origine.' $computerKey $link
        }
    }

    $allowed = ($blockers.Count -eq 0)
    if (-not $allowed) {
        foreach ($step in $steps) {
            if ($step.Action -in @('Copier','Adopter','Importer','Ajouter')) { $step.Action = 'Reporter'; $step.Reason = 'Reporte, rien n est ecrit : ' + $step.Reason }
        }
    }
    $all = $steps.ToArray()
    $copy = @($all | Where-Object { $_.Action -ceq 'Copier' }).Count
    $adopt = @($all | Where-Object { $_.Action -ceq 'Adopter' }).Count
    $import = @($all | Where-Object { $_.Action -ceq 'Importer' }).Count
    $add = @($all | Where-Object { $_.Action -ceq 'Ajouter' }).Count
    return [pscustomobject]@{
        Allowed=$allowed;Blockers=$blockers.ToArray();Steps=$all;Trace=$trace.ToArray();Marker=$marker;Already=[bool]$already
        CopyCount=$copy;AdoptCount=$adopt;ImportCount=$import;AddCount=$add
        KeepCount=@($all | Where-Object { $_.Action -ceq 'Conserver' }).Count
        SkipCount=@($all | Where-Object { $_.Action -ceq 'Ignorer' }).Count
        RefusedCount=@($all | Where-Object { $_.Action -ceq 'Refuser' }).Count
        RejectedCount=@($all | Where-Object { $_.Action -ceq 'Rejeter' }).Count
        DeferredCount=@($all | Where-Object { $_.Action -ceq 'Reporter' }).Count
        WriteCount=($copy + $adopt + $import + $add);RequiresBackup=(($adopt + $import + $add) -gt 0)
        ModifiesLegacyDatabase=($adopt -gt 0);SourceKept=(@($all | Where-Object { $_.Action -in @('Supprimer','Deplacer') }).Count -eq 0)
    }
}

function Get-DomeniaMigratedState {
    # The Domenia state a migration plan would produce, computed without touching anything. A refused plan changes
    # nothing. Copied names are added, an adopted base gets its domenia_schema revision, an imported table gets its
    # rows, links are appended; nothing present before is removed or replaced.
    param($Current,$Plan)
    $configs = New-Object 'System.Collections.Generic.List[string]'
    $seen = @{}
    foreach ($name in @(Get-DomeniaMember $Current 'ConfigFiles' @())) {
        if ($name -and (-not $seen.ContainsKey([string]$name))) { $seen[[string]$name] = $true; $configs.Add([string]$name) }
    }
    $links = New-Object 'System.Collections.Generic.List[object]'
    foreach ($link in @(Get-DomeniaMember $Current 'Links' @())) { if ($null -ne $link) { $links.Add($link) } }
    $sourceTables = Get-DomeniaMember $Current 'Tables' $null
    $tables = @{}
    foreach ($table in @('ad_objects','park_state','user_machine_links','user_scan_history','secret_state')) {
        $value = Get-DomeniaReleaseMapValue $sourceTables $table $null
        if ($null -ne $value) { $tables[$table] = [int]$value }
    }
    $database = Get-DomeniaMember $Current 'Database' $null
    $applied = ($null -ne $Plan) -and ((Get-DomeniaMember $Plan 'Allowed' $false) -eq $true)
    if ($applied) {
        foreach ($step in @(Get-DomeniaMember $Plan 'Steps' @())) {
            $action = [string](Get-DomeniaMember $step 'Action' '')
            $target = [string](Get-DomeniaMember $step 'Target' '')
            if (($action -ceq 'Copier') -and $target -and (-not $seen.ContainsKey($target))) { $seen[$target] = $true; $configs.Add($target) }
            elseif (($action -ceq 'Adopter') -and ($null -ne $database)) {
                $database = [pscustomobject]@{Name=[string](Get-DomeniaMember $database 'Name' '');SchemaVersion=[string](Get-DomeniaMember $database 'SchemaVersion' '');DomeniaSchema='1';BaseDn=[string](Get-DomeniaMember $database 'BaseDn' '')}
            }
            elseif ($action -ceq 'Importer') { $item = Get-DomeniaMember $step 'Item' $null; $tables[$target] = [int](Get-DomeniaMember $item 'Rows' 0) }
            elseif ($action -ceq 'Ajouter') {
                $item = Get-DomeniaMember $step 'Item' $null
                if ($null -ne $item) { $links.Add($item); $tables[$target] = 1 + [int](Get-DomeniaMember $tables $target 0) }
            }
        }
    }
    $migrationMarker = [string](Get-DomeniaMember $Current 'MigrationMarker' '')
    if ($applied -and ([int]$Plan.ImportCount + [int]$Plan.AddCount -gt 0)) { $migrationMarker = [string]$Plan.Marker }
    return [pscustomobject]@{Domain=[string](Get-DomeniaMember $Current 'Domain' '');ConfigFiles=$configs.ToArray();Database=$database;Tables=$tables;Links=$links.ToArray();MigrationMarker=$migrationMarker}
}

function Test-DomeniaMigrationIdempotent {
    # Runs the plan (only when it is allowed), then plans again on the result: a second run must have nothing to write,
    # no computer may hold two links because of the migration, no link may be lost, and no Domenia configuration
    # present before may be a copy target.
    param($Legacy,$Current,[string[]]$SupportedSchemaVersions=@('11'),[ValidateSet('Explicit','Startup')][string]$Trigger='Explicit')
    $first = Get-DomeniaMigrationPlan $Legacy $Current $SupportedSchemaVersions -Trigger $Trigger
    $after = Get-DomeniaMigratedState $Current $first
    $second = Get-DomeniaMigrationPlan $Legacy $after $SupportedSchemaVersions -Trigger $Trigger
    $existing = @{}
    foreach ($name in @(Get-DomeniaMember $Current 'ConfigFiles' @())) { if ($name) { $existing[[string]$name] = $true } }
    $overwritten = @(@($first.Steps) | Where-Object { ($_.Action -ceq 'Copier') -and $existing.ContainsKey([string]$_.Target) } | ForEach-Object { [string]$_.Target })
    $before = @{}
    foreach ($link in @(Get-DomeniaMember $Current 'Links' @())) {
        if ($null -eq $link) { continue }
        $key = ConvertTo-DomeniaMigrationComputerKey ([string](Get-DomeniaMember $link 'Computer' ''))
        $before[$key] = 1 + [int](Get-DomeniaMember $before $key 0)
    }
    $counts = @{}
    foreach ($link in @($after.Links)) {
        if ($null -eq $link) { continue }
        $key = ConvertTo-DomeniaMigrationComputerKey ([string](Get-DomeniaMember $link 'Computer' ''))
        $counts[$key] = 1 + [int](Get-DomeniaMember $counts $key 0)
    }
    $duplicates = @(@($counts.Keys) | Where-Object { ([int]$counts[$_] -gt 1) -and ([int]$counts[$_] -gt [int](Get-DomeniaMember $before $_ 0)) })
    $lost = @(@($before.Keys) | Where-Object { [int](Get-DomeniaMember $counts $_ 0) -lt [int]$before[$_] }).Count
    $idempotent = (($second.WriteCount -eq 0) -and ($overwritten.Count -eq 0) -and ($duplicates.Count -eq 0) -and ($lost -eq 0))
    return [pscustomobject]@{Idempotent=$idempotent;Applied=[bool]$first.Allowed;FirstWrites=$first.WriteCount;SecondWrites=$second.WriteCount;DuplicateLinks=$duplicates;OverwrittenConfig=$overwritten;LostLinks=$lost;First=$first;Second=$second;State=$after}
}

function Get-DomeniaRelationKind {
    # Closed vocabulary derived from the stored source text of a relation. The order matters:
    # an AD owner attribute is a clue, a LogonUI value or a profile is history, the current console is an observation.
    param([AllowEmptyString()][AllowNull()][string]$Source)
    $text = [string]$Source
    if ($text -match '(?i)responsable|managedby') { return 'Indice' }
    if ($text -match '(?i)saisie manuelle|manual|manuel|declar|affect') { return 'Affectation' }
    if ($text -match '(?i)import|csv') { return 'Importe' }
    if ($text -match '(?i)rdp|wts|session distante|terminal') { return 'SessionRdp' }
    if ($text -match '(?i)historique|journal|event|4624|harvest|logonui|logon|profil|registre') { return 'Historique' }
    if ($text -match '(?i)console|cim|dcom|explorer|interactive|computersystem|quser|utilisateur courant|winrm') { return 'Console' }
    if ($text -match '(?i)description|kerberos|indice|attribut|inventaire|wapt|glpi|mention') { return 'Indice' }
    return 'Inconnu'
}

function ConvertTo-DomeniaRelationUtcDate {
    # Date of a relation as a UTC DateTime, or $null. Relation dates are stored as UTC ISO 8601 ("o"). A date
    # without offset was written in local time before RC1.14 (manual and imported rows "yyyy-MM-dd HH:mm:ss",
    # Live rows "s"): it is read as local time, never as UTC. Texts are parsed once (same rules as
    # ConvertTo-DomeniaUtcDate -AssumeLocal) and kept in a bounded session memo.
    param($Value)
    if ($null -ne $Value -and $Value -isnot [string]) { return (ConvertTo-DomeniaUtcDate $Value -AssumeLocal) }
    $text = [string]$Value
    $memo = $script:DomeniaRelationWhenMemo
    if ($null -eq $memo -or $memo.Count -ge 50000) {
        $memo = New-Object 'System.Collections.Generic.Dictionary[string,object]' ([StringComparer]::Ordinal)
        $script:DomeniaRelationWhenMemo = $memo
    }
    $known = $null
    if ($memo.TryGetValue($text,[ref]$known)) { return $known }
    $utc = $null
    $trimmed = $text.Trim()
    if ($trimmed) {
        # An AD FILETIME written as digits keeps the general reader; every relation date is a date text.
        if ($trimmed -match '^\d{12,19}$') { $utc = ConvertTo-DomeniaUtcDate $trimmed -AssumeLocal }
        else {
            $parsed = [datetime]::MinValue
            $styles = [Globalization.DateTimeStyles]::AssumeLocal -bor [Globalization.DateTimeStyles]::AdjustToUniversal
            if ([datetime]::TryParse($trimmed,[Globalization.CultureInfo]::InvariantCulture,$styles,[ref]$parsed)) { $utc = $parsed }
        }
    }
    $memo[$text] = $utc
    return $utc
}

function Select-DomeniaPrimaryRelation {
    # The relation shown first for a workstation: a declared assignment, otherwise the most recent relation.
    param([object[]]$Relations=@())
    $best = $null; $bestDeclared = $false; $bestWhen = $null
    foreach ($relation in @($Relations)) {
        if ($null -eq $relation) { continue }
        $kind = [string](Get-DomeniaMember $relation 'Kind' '')
        if (-not $kind) { $kind = Get-DomeniaRelationKind ([string](Get-DomeniaMember $relation 'Source' '')) }
        $declared = ($kind -eq 'Affectation')
        $when = ConvertTo-DomeniaRelationUtcDate (Get-DomeniaMember $relation 'When' $null)
        if ($null -eq $best) { $best = $relation; $bestDeclared = $declared; $bestWhen = $when; continue }
        if ($declared -and -not $bestDeclared) { $best = $relation; $bestDeclared = $true; $bestWhen = $when; continue }
        if ($declared -ne $bestDeclared) { continue }
        if ($null -ne $when -and ($null -eq $bestWhen -or $when -gt $bestWhen)) { $best = $relation; $bestWhen = $when }
    }
    return $best
}

function Normalize-LinkComputer {
    param([string]$Computer)
    $c = ($Computer + "").Trim()
    if ([string]::IsNullOrWhiteSpace($c)) { return "" }
    $c = $c.Trim("`"", " ", "`t", "`r", "`n")
    if ($c.EndsWith("$")) { $c = $c.Substring(0, $c.Length - 1) }
    if ($c.Contains(".")) { $c = $c.Split(".")[0] }
    return $c.ToUpperInvariant()
}

function Normalize-LinkUser {
    param([string]$User)
    $u = ($User + "").Trim()
    if ([string]::IsNullOrWhiteSpace($u)) { return "" }
    $u = $u.Trim("`"", " ", "`t", "`r", "`n")
    $slash = [string][char]92
    if ($u.Contains($slash)) { $u = $u.Split($slash)[-1] }
    if ($u.Contains("@")) { $u = $u.Split("@")[0] }
    $dollar = [string][char]36
    if ($u.EndsWith($dollar)) { return "" }
    $bad = @("SYSTEM", "LOCAL SERVICE", "NETWORK SERVICE", "ANONYMOUS LOGON", "DWM-1", "DWM-2", "UMFD-0", "UMFD-1", "DEFAULTUSER0", "ADMINISTRATEUR", "ADMINISTRATOR")
    if ($bad -contains $u.ToUpperInvariant()) { return "" }
    return $u
}

function Get-DomeniaStoreBackupDirectory {
    $path = Join-Path ([IO.Path]::GetDirectoryName((Get-DomeniaDatabasePath))) 'Backups'
    if (-not [IO.Directory]::Exists($path)) { [void][IO.Directory]::CreateDirectory($path) }
    return $path
}

function Backup-DomeniaDatabase {
    param([switch]$IfNeeded,[switch]$Migration)
    $dbPath = Get-DomeniaDatabasePath
    if (-not [IO.File]::Exists($dbPath)) { return $null }
    $backupDir = Get-DomeniaStoreBackupDirectory
    # D115: a backup taken before a schema migration lives outside the normal rotation and is never pruned here.
    if ($Migration) {
        $backupDir = Join-Path $backupDir 'migrations'
        [void][IO.Directory]::CreateDirectory($backupDir)
    }
    if ($IfNeeded -and (-not $Migration)) {
        $latest = Get-ChildItem -LiteralPath $backupDir -Filter 'Domenia-*.db' -File -ErrorAction SilentlyContinue | Sort-Object LastWriteTime -Descending | Select-Object -First 1
        if ($null -ne $latest -and ((Get-Date) - $latest.LastWriteTime).TotalHours -lt 20) { return [string]$latest.FullName }
    }
    $stamp = (Get-Date -Format 'yyyyMMdd-HHmmss-fff') + '-' + [guid]::NewGuid().ToString('N').Substring(0,8)
    if ($Migration) { $stamp = 'migration-' + $stamp }
    $dest = Join-Path $backupDir ('Domenia-' + $stamp + '.db')
    $temporary = $dest + '.partial'
    $sourceDb = [IntPtr]::Zero; $targetDb = [IntPtr]::Zero; $backup = [IntPtr]::Zero; $mainPtr = [IntPtr]::Zero
    $complete = $false
    try {
        $sourceDb = Open-DomeniaDatabase -Path $dbPath -ReadOnly
        $targetDb = Open-DomeniaDatabase -Path $temporary
        $mainPtr = New-DomeniaUtf8Ptr 'main'
        $backup = [Domenia.WinSqliteNative]::sqlite3_backup_init($targetDb,$mainPtr,$sourceDb,$mainPtr)
        if ($backup -eq [IntPtr]::Zero) { throw 'Initialisation de la sauvegarde SQLite impossible.' }
        $watch = [Diagnostics.Stopwatch]::StartNew()
        $budget = [Math]::Max(5,[Math]::Min(120,[int](Get-CfgValue 'LocalStore' 'BackupTimeoutSeconds' 30)))
        do {
            $rc = [Domenia.WinSqliteNative]::sqlite3_backup_step($backup,256)
            if ($rc -eq 101) { break }
            if ($rc -notin @(0,5,6)) { throw "Sauvegarde SQLite : code $rc." }
            if ($watch.Elapsed.TotalSeconds -ge $budget) { throw "Sauvegarde SQLite interrompue apres $budget secondes. L'original est intact." }
            if ($rc -in @(5,6)) { Start-Sleep -Milliseconds 25 }
        } while ($true)
        $finish = [Domenia.WinSqliteNative]::sqlite3_backup_finish($backup); $backup = [IntPtr]::Zero
        if ($finish -ne 0) { throw "Finalisation de sauvegarde SQLite : code $finish." }
        $check = @(Invoke-DomeniaDbQuery -Sql 'PRAGMA quick_check;' -DatabaseHandle $targetDb)
        if ($check.Count -ne 1 -or [string]$check[0].quick_check -cne 'ok') { throw 'La sauvegarde ne passe pas le controle SQLite.' }
        Close-DomeniaDatabase $targetDb; $targetDb = [IntPtr]::Zero
        Close-DomeniaDatabase $sourceDb; $sourceDb = [IntPtr]::Zero
        [IO.File]::Move($temporary,$dest)
        $complete = $true
        if (-not $Migration) {
            $keep = [Math]::Max(2,[Math]::Min(30,[int](Get-CfgValue 'LocalStore' 'DatabaseBackupCount' 7)))
            Get-ChildItem -LiteralPath $backupDir -Filter 'Domenia-*.db' -File | Sort-Object LastWriteTime -Descending | Select-Object -Skip $keep | ForEach-Object {
                Remove-Item -LiteralPath $_.FullName -Force -ErrorAction SilentlyContinue
            }
        }
        return $dest
    }
    finally {
        if ($backup -ne [IntPtr]::Zero) { [void][Domenia.WinSqliteNative]::sqlite3_backup_finish($backup) }
        Close-DomeniaDatabase $targetDb; Close-DomeniaDatabase $sourceDb
        if ($mainPtr -ne [IntPtr]::Zero) { [Runtime.InteropServices.Marshal]::FreeHGlobal($mainPtr) }
        if (-not $complete) {
            foreach ($suffix in @('','-wal','-shm','-journal')) { Remove-Item -LiteralPath ($temporary + $suffix) -Force -ErrorAction SilentlyContinue }
        }
    }
}

function ConvertTo-DomeniaLegacyNumber {
    param([string]$Text,[long]$Maximum=[int]::MaxValue)
    if ([string]::IsNullOrWhiteSpace($Text)) { return [long]0 }
    $value=[long]0
    if (-not [long]::TryParse($Text,[Globalization.NumberStyles]::Integer,[Globalization.CultureInfo]::InvariantCulture,[ref]$value) -or $value -lt 0 -or $value -gt $Maximum) { throw 'Nombre historique invalide.' }
    return $value
}

function ConvertTo-DomeniaLegacyDate {
    param([string]$Text,[switch]$Required)
    if ([string]::IsNullOrWhiteSpace($Text)) {
        if ($Required) { throw 'Date historique absente.' }
        return ''
    }
    $value=[datetime]::MinValue
    if (-not [datetime]::TryParse($Text,[Globalization.CultureInfo]::InvariantCulture,[Globalization.DateTimeStyles]::RoundtripKind,[ref]$value)) { throw 'Date historique invalide.' }
    return $value.ToString('o',[Globalization.CultureInfo]::InvariantCulture)
}

function Read-DomeniaLegacySource {
    # The same locked file supplies its hash and its rows. A writer cannot alter it between these reads.
    param([string]$Path,[ValidateSet('Objets','Parc','Recherches','Secrets','Liens')][string]$Kind)
    $rows=[Collections.Generic.List[object]]::new();$rejected=0;$count=0
    $stream=[IO.File]::Open($Path,[IO.FileMode]::Open,[IO.FileAccess]::Read,[IO.FileShare]::Read)
    $reader=$null
    try {
        if ($stream.Length -gt 128MB) { throw ('Fichier historique trop volumineux : '+[IO.Path]::GetFileName($Path)) }
        $hash=[Security.Cryptography.SHA256]::Create()
        try { $sha=[BitConverter]::ToString($hash.ComputeHash($stream)).Replace('-','').ToLowerInvariant() } finally { $hash.Dispose() }
        $stream.Position=0
        if ($Kind -eq 'Liens') {
            Import-Csv -LiteralPath $Path -Encoding UTF8 -ErrorAction Stop | ForEach-Object {
                $count++
                if ($count -gt 250000) { throw 'Plus de 250000 lignes dans une source historique.' }
                try {
                    $computer=Normalize-LinkComputer ([string]$_.Computer);$user=Normalize-LinkUser ([string]$_.UserLogin)
                    if (-not $computer -or -not $user) { throw 'Association incomplete.' }
                    $verified=$false;$flag=[string]$_.VerifiedInAD
                    if ($flag -eq '1') { $verified=$true }
                    elseif ($flag -ne '' -and $flag -ne '0' -and (-not [bool]::TryParse($flag,[ref]$verified))) { throw 'Indicateur historique invalide.' }
                    $rows.Add([pscustomobject]@{
                        UserLogin=$user;Computer=$computer;Source=[string]$_.Source
                        Confidence=[int](ConvertTo-DomeniaLegacyNumber ([string]$_.Confidence) 100);VerifiedInAD=$verified
                        When=(ConvertTo-DomeniaLegacyDate ([string]$_.When) -Required);Details=[string]$_.Details
                        UserGuid=[string]$_.UserGuid;ComputerGuid=[string]$_.ComputerGuid;UserDn=[string]$_.UserDn;ComputerDn=[string]$_.ComputerDn
                    })
                } catch { $rejected++ }
            }
        } else {
            $reader=[IO.StreamReader]::new($stream,[Text.Encoding]::UTF8,$true,4096,$true)
            while ($null -ne ($line=$reader.ReadLine())) {
                $count++
                if ($count -gt 250001) { throw 'Plus de 250000 lignes dans une source historique.' }
                if (-not $line.Trim()) { continue }
                $f=$line.Split([char]9)
                if ($count -eq 1 -and (($Kind -eq 'Objets' -and $f[0] -eq 'Type') -or ($Kind -in @('Parc','Secrets') -and $f[0] -eq 'Computer') -or ($Kind -eq 'Recherches' -and $f[0] -eq 'Login'))) { continue }
                try {
                    $row=$null
                    switch ($Kind) {
                        'Objets' {
                            if ($f.Length -lt 9 -or [string]::IsNullOrWhiteSpace($f[8])) { throw 'Objet incomplet.' }
                            $row=[pscustomobject]@{Type=$f[0];Name=$f[1];Login=$f[2];Upn=$f[3];Display=$f[4];Description=$f[5];Extra=$f[6];State=$f[7];DN=$f[8].Trim();WhenChanged='';Usn=[long]0;LastLogon='';Guid=''}
                            if ($f.Length -ge 10) { $row.WhenChanged=ConvertTo-DomeniaLegacyDate $f[9] }
                            if ($f.Length -ge 11) { $row.Usn=ConvertTo-DomeniaLegacyNumber $f[10] ([long]::MaxValue) }
                            if ($f.Length -ge 12) { $row.LastLogon=ConvertTo-DomeniaLegacyDate $f[11] }
                            if ($f.Length -ge 13) { $row.Guid=$f[12] }
                        }
                        'Parc' {
                            if ($f.Length -lt 4) { throw 'Etat parc incomplet.' }
                            $computer=Normalize-LinkComputer $f[0]
                            if (-not $computer) { throw 'Poste absent.' }
                            $attempts=0;if ($f.Length -ge 5) { $attempts=ConvertTo-DomeniaLegacyNumber $f[4] }
                            $row=[pscustomobject]@{Key=$computer.ToUpperInvariant();Computer=$computer;LastProbe=(ConvertTo-DomeniaLegacyDate $f[1]);Status=$f[2];User=$f[3];Attempts=[int]$attempts}
                        }
                        'Recherches' {
                            if ($f.Length -lt 7 -or -not $f[0].Trim() -or $f[2] -notin @('0','1')) { throw 'Recherche incomplete.' }
                            $row=[pscustomobject]@{Login=$f[0].Trim();At=(ConvertTo-DomeniaLegacyDate $f[1]);Scanned=($f[2] -eq '1');Candidates=[int](ConvertTo-DomeniaLegacyNumber $f[3]);Reachable=[int](ConvertTo-DomeniaLegacyNumber $f[4]);Probed=[int](ConvertTo-DomeniaLegacyNumber $f[5]);Found=$f[6]}
                        }
                        'Secrets' {
                            if ($f.Length -lt 8) { throw 'Metadonnees incompletes.' }
                            $computer=Normalize-LinkComputer $f[0]
                            if (-not $computer) { throw 'Poste absent.' }
                            # Never import the free-form detail column: only the known metadata fields.
                            $row=[pscustomobject]@{Computer=$computer;At=(ConvertTo-DomeniaLegacyDate $f[1]);BitLockerKeys=[int](ConvertTo-DomeniaLegacyNumber $f[2]);BitLockerLast=(ConvertTo-DomeniaLegacyDate $f[3]);LapsScheme=$f[4];LapsExpiry=(ConvertTo-DomeniaLegacyDate $f[5]);Verdict=$f[6]}
                        }
                    }
                    $rows.Add($row)
                } catch { $rejected++ }
            }
        }
        if ($rows.Count -gt 250000) { throw 'Plus de 250000 lignes dans une source historique.' }
        return [pscustomobject]@{Kind=$Kind;Path=$Path;Sha256=$sha;Rows=$rows.ToArray();Rejected=$rejected}
    } finally { if ($null -ne $reader) { $reader.Dispose() };$stream.Dispose() }
}

function Get-DomeniaLegacySnapshot {
    param([string]$LocalAppData=$env:LOCALAPPDATA)
    $roots=[Collections.Generic.List[string]]::new()
    if ($script:DataDir) { $roots.Add([IO.Path]::GetFullPath([string]$script:DataDir)) }
    if ($LocalAppData) { $roots.Add((Join-Path $LocalAppData 'DOMENIA')) }
    $names=[ordered]@{Objets='Index\objets.tsv';Parc='Index\parc.tsv';Recherches='Index\recherches.tsv';Secrets='Index\secrets-etat.tsv';Liens='Domenia-user-machine-links.csv'}
    $sources=[Collections.Generic.List[object]]::new();$data=@{};$rejected=0;$domains=@{}
    foreach ($kind in $names.Keys) {
        $data[$kind]=@()
        foreach ($root in $roots) {
            $path=Join-Path $root $names[$kind]
            if (-not [IO.File]::Exists($path)) { continue }
            $source=Read-DomeniaLegacySource -Path $path -Kind $kind
            $sources.Add($source);$data[$kind]=@($source.Rows);$rejected+=$source.Rejected
            break
        }
    }
    foreach ($row in $data.Objets) {
        $match=[regex]::Match([string]$row.DN,'(?i)(?:^|,)\s*(DC=[^,=\s]+(?:\s*,\s*DC=[^,=\s]+)*)$')
        if (-not $match.Success) { throw 'Domaine non identifiable dans les objets historiques.' }
        $dn=($match.Groups[1].Value -split ',' | ForEach-Object { $_.Trim() }) -join ','
        $domain=ConvertTo-DomeniaMigrationDomain $dn
        $domains[$domain]=$dn
        $row.DN=([string]$row.DN).Substring(0,$match.Index)+$(if ($match.Index -gt 0) { ',' } else { '' })+$dn
    }
    if ($domains.Count -gt 1) { throw 'Plusieurs domaines dans les objets historiques : reprise refusee.' }
    $baseDn='';if ($domains.Count -eq 1) { $baseDn=[string]@($domains.Values)[0] }
    # Always use the Relations rule, independent of feature flags or multi-relation display mode.
    $groups=@{}
    foreach ($link in $data.Liens) {
        $key=([string]$link.Computer).ToUpperInvariant()
        if (-not $groups.ContainsKey($key)) { $groups[$key]=[Collections.Generic.List[object]]::new() }
        $groups[$key].Add($link)
    }
    $links=[Collections.Generic.List[object]]::new()
    foreach ($key in @($groups.Keys | Sort-Object)) {
        $link=Select-DomeniaPrimaryRelation -Relations $groups[$key].ToArray()
        $origin=[string]$link.Source
        $link.Details=('Reprise historique ; source d origine : '+$origin+'. '+[string]$link.Details).Trim()
        $link.Source='Import CSV'
        $links.Add($link)
    }
    $data.Liens=$links.ToArray()
    foreach ($kind in @('Objets','Parc','Recherches','Secrets')) {
        $keys=@{}
        foreach ($row in @($data[$kind])) {
            $key=switch ($kind) {
                'Objets' { if ([string]$row.Guid) { [string]$row.Guid } else { ([string]$row.Type)+'|'+([string]$row.DN) } }
                'Parc' { [string]$row.Key }
                'Recherches' { [string]$row.Login }
                'Secrets' { [string]$row.Computer }
            }
            if ($keys.ContainsKey($key)) { throw ('Doublon dans les donnees '+$kind+'. Corrigez la source avant reprise.') }
            $keys[$key]=$true
        }
    }
    $marker=Get-DomeniaTextHash ((@($sources | ForEach-Object { $_.Kind+'|'+$_.Path+'|'+$_.Sha256 }) -join [Environment]::NewLine))
    return [pscustomobject]@{Data=$data;Sources=$sources.ToArray();BaseDn=$baseDn;Marker=$marker;Rejected=$rejected}
}

function New-DomeniaLegacyImportPlan {
    param([string]$LocalAppData=$env:LOCALAPPDATA)
    $path=[string]$script:DatabaseScopedPath
    if (-not $path -or -not [IO.File]::Exists($path)) { throw 'Base du contexte non disponible : reprise impossible.' }
    $snapshot=Get-DomeniaLegacySnapshot -LocalAppData $LocalAppData
    $db=Open-DomeniaDatabase -Path $path -ReadOnly
    try {
        $tables=[ordered]@{}
        foreach ($table in @('ad_objects','park_state','user_scan_history','secret_state','user_machine_links')) {
            $tables[$table]=[long](@(Invoke-DomeniaDbQuery ("SELECT count(*) AS n FROM "+$table+';') $db)[0].n)
        }
        $links=@(Invoke-DomeniaDbQuery 'SELECT computer AS Computer FROM user_machine_links ORDER BY computer_key;' $db)
        $sync=@(Invoke-DomeniaDbQuery "SELECT scope,base_dn,details FROM sync_state WHERE scope IN ('directory','legacy_import') ORDER BY scope;" $db)
        $schema=@(Invoke-DomeniaDbQuery "SELECT key,value FROM schema_info WHERE key IN ('schema_version','domenia_schema') ORDER BY key;" $db)
    } finally { Close-DomeniaDatabase $db }
    $marker='';$directoryDn='';$version='';$revision=''
    foreach ($row in $sync) {
        if ($row.scope -eq 'legacy_import') { $marker=([string]$row.details) -replace '^marker=','' }
        if ($row.scope -eq 'directory') { $directoryDn=[string]$row.base_dn }
    }
    foreach ($row in $schema) { if ($row.key -eq 'schema_version') { $version=[string]$row.value } else { $revision=[string]$row.value } }
    $stores=@($snapshot.Sources | ForEach-Object { [pscustomobject]@{Kind=$_.Kind;Path=$_.Path;Rows=@($snapshot.Data[$_.Kind]).Count;Links=$(if ($_.Kind -eq 'Liens') { @($snapshot.Data.Liens) } else { @() })} })
    $legacy=[pscustomobject]@{Domain=$snapshot.BaseDn;ConfigFiles=@();Stores=$stores;Marker=$snapshot.Marker}
    $current=[pscustomobject]@{Domain=[string]$script:Conn.BaseDn;ConfigFiles=@();Tables=$tables;Links=$links;MigrationMarker=$marker;Database=[pscustomobject]@{Name=[IO.Path]::GetFileName($path);SchemaVersion=$version;DomeniaSchema=$revision;BaseDn=$directoryDn}}
    $plan=Get-DomeniaMigrationPlan $legacy $current -Trigger Explicit
    if (-not (Test-DomeniaMigrationIdempotent $legacy $current -Trigger Explicit).Idempotent) { throw 'La simulation ne garantit pas une reprise sans doublons.' }
    if ($directoryDn -and (ConvertTo-DomeniaMigrationDomain $directoryDn) -ne (ConvertTo-DomeniaMigrationDomain ([string]$script:Conn.BaseDn))) { throw 'Le domaine de la base differe du contexte courant.' }
    if ($revision -ne '1') { throw 'Base non preparee pour Domenia : reprise refusee.' }
    $fingerprint=Get-DomeniaTextHash (([ordered]@{Marker=$snapshot.Marker;Path=$path;Epoch=[long]$script:SessionEpoch;Domain=$current.Domain;Tables=$tables;Links=$links;Sync=$sync;Schema=$schema}) | ConvertTo-Json -Depth 8 -Compress)
    $payload=[pscustomobject]@{Marker=$snapshot.Marker;BaseDn=$snapshot.BaseDn;At=[datetime]::UtcNow.ToString('o');Objects=@($snapshot.Data.Objets);Park=@($snapshot.Data.Parc);UserScans=@($snapshot.Data.Recherches);Secrets=@($snapshot.Data.Secrets);Links=@($snapshot.Data.Liens)}
    $plan | Add-Member -NotePropertyMembers @{Fingerprint=$fingerprint;Path=$path;Epoch=[long]$script:SessionEpoch;Payload=$payload;Sources=$snapshot.Sources;RejectedLines=$snapshot.Rejected;Queued=$false}
    return $plan
}

function Get-DomeniaDatabasePath { return [string]$script:DatabaseScopedPath }
function Get-CfgValue { param($Section,$Key,$Default) if ($Key -eq 'BackupTimeoutSeconds') { return $Payload.BackupTimeoutSeconds };return $Default }
$script:DatabaseScopedPath=[string]$Payload.Path
$script:DataDir=[string]$Payload.DataDir
$script:SessionEpoch=[long]$Payload.Epoch
$script:Conn=[pscustomobject]@{BaseDn=[string]$Payload.BaseDn}
$plan=New-DomeniaLegacyImportPlan -LocalAppData ([string]$Payload.LocalAppData)
if ($Payload.Mode -eq 'Prepare') {
    if (-not $Payload.ExpectedFingerprint -or $plan.Fingerprint -cne [string]$Payload.ExpectedFingerprint) { throw 'Les donnees ou le contexte ont change. Refaites la simulation.' }
    if (-not $plan.Allowed) { throw ($plan.Blockers -join [Environment]::NewLine) }
    if ($plan.WriteCount -gt 0) {
        $backup=Backup-DomeniaDatabase -Migration
        if (-not $backup -or -not [IO.File]::Exists([string]$backup)) { throw 'Sauvegarde de migration non confirmee.' }
        $plan | Add-Member -NotePropertyName BackupPath -NotePropertyValue ([string]$backup)
    }
} elseif ($Payload.Mode -ne 'Preview') { throw 'Mode de reprise inconnu.' }
return $plan
'@
}
